// src/components/TonalitySelector.jsx

import React from 'react';
import { SHARP } from '../data/vocabulary';

function TonalitySelector({ keyPairs, onSelect }) {
   return (
     <div>
       <h2 className="text-xl font-semibold mb-4">�������� �����������</h2>
       <table className="min-w-full divide-y divide-gray-700">
         <thead className="bg-gray-800">
           <tr>
             <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">�</th>
             <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">����� (M)</th>
             <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">����� (m)</th>
             <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-400 uppercase tracking-wider">�������� �����</th>
           </tr>
         </thead>
         <tbody className="bg-gray-700 divide-y divide-gray-800">
           {keyPairs.map(([major, minor], index) => (
             <tr key={major} onClick={() => onSelect(`${index+1},maj`)} className="hover:bg-blue-800 cursor-pointer">
               <td className="px-6 py-4 whitespace-nowrap">{index + 1}</td>
               <td className="px-6 py-4 whitespace-nowrap">{major}</td>
               <td className="px-6 py-4 whitespace-nowrap">{minor}</td>
               <td className="px-6 py-4 whitespace-nowrap">{major.includes('dur') ? major.replace('dur', '').split('#').join(SHARP).split('b').join(FLAT) : ''}</td>
             </tr>
           ))}
         </tbody>
       </table>
     </div>
   );
 }
 
 export default TonalitySelector;
